// The drift guard for the burial-ground mirror — the same contract as
// ../mosques/sync.test.ts, for the same reason: ./data.json is GENERATED by `pnpm sync:data`
// from the web app's canonical list, and a mirror nothing checks goes stale without a sound
// (the mosque mirror did, for three weeks in 2026-07).
//
// If this fails: run `pnpm sync:data`. Do NOT hand-edit data.json to make it pass —
// corrections go in apps/web/src/data/begravningsplatser-sverige.json.
import { describe, expect, it } from '@jest/globals';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import mobileData from './data.json';

const WEB_LIST = join(__dirname, '../../../../web/src/data/begravningsplatser-sverige.json');

/** The canonical list, or null when the web app isn't checked out beside us (the mobile
 *  app is its own pnpm workspace and can be cloned alone). */
function readCanonical(): unknown[] | null {
  try {
    return JSON.parse(readFileSync(WEB_LIST, 'utf8')) as unknown[];
  } catch {
    return null;
  }
}

const canonical = readCanonical();

describe('burial-ground data mirrors the canonical web list', () => {
  // A plain deep-equal is fine at this size (~80 records): the diff it prints names the
  // record and field that moved, which is what the mosque test had to build by hand.
  (canonical === null ? it.skip : it)('is identical to the web file', () => {
    expect(mobileData).toEqual(canonical);
  });
});
